import assert from 'node:assert/strict';
const sorted=x=>x.sort((a,b)=>a-b);
const input=[9,1,1]; assert.deepEqual(sorted(input),[1,1,9]); assert.deepEqual(input,[9,1,1]); assert.deepEqual(sorted([]),[]);

import assert from 'node:assert/strict';
const sorted=x=>x.toSorted((a,b)=>a-b);
const input=[9,1,1]; assert.deepEqual(sorted(input),[1,1,9]); assert.deepEqual(input,[9,1,1]); assert.deepEqual(sorted([]),[]);
